CREATE TABLE user_activity(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,kind TEXT NOT NULL,target TEXT,summary TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX journey_activity_date ON user_activity(created_at DESC,id DESC);
CREATE INDEX journey_activity_user_date ON user_activity(user_id,created_at DESC,id DESC);
CREATE TRIGGER journey_activity_rating AFTER INSERT ON ratings  BEGIN INSERT INTO user_activity(user_id,kind,target,summary,created_at) VALUES(NEW.user_id,'rating',NEW.video_id,'Rated a video '||NEW.score||'/5',strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER journey_activity_rating_edit AFTER UPDATE OF score ON ratings WHEN OLD.score<>NEW.score BEGIN INSERT INTO user_activity(user_id,kind,target,summary,created_at) VALUES(NEW.user_id,'rating',NEW.video_id,'Changed a video rating to '||NEW.score||'/5',strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER journey_activity_contribution AFTER INSERT ON contributions  BEGIN INSERT INTO user_activity(user_id,kind,target,summary,created_at) VALUES(NEW.user_id,'contribution',NEW.video_id,CASE NEW.kind WHEN 'comment' THEN 'Submitted a comment for review' WHEN 'submission' THEN 'Suggested a reaction video' ELSE 'Reported a video for review' END,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER journey_activity_chat AFTER INSERT ON chat_messages  BEGIN INSERT INTO user_activity(user_id,kind,target,summary,created_at) VALUES(NEW.user_id,'chat',NEW.room,'Posted a chat message in '||NEW.room,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER journey_activity_follow AFTER INSERT ON follows  BEGIN INSERT INTO user_activity(user_id,kind,target,summary,created_at) VALUES(NEW.user_id,'follow',NEW.target,'Followed a '||NEW.kind,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER journey_activity_unfollow AFTER DELETE ON follows  BEGIN INSERT INTO user_activity(user_id,kind,target,summary,created_at) VALUES(OLD.user_id,'follow',OLD.target,'Unfollowed a '||OLD.kind,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER journey_activity_watch AFTER INSERT ON watch  BEGIN INSERT INTO user_activity(user_id,kind,target,summary,created_at) VALUES(NEW.user_id,'watch',NEW.video_id,'Set watch status to '||NEW.status||CASE WHEN NEW.favorite=1 THEN '; added to favorites' ELSE '' END,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER journey_activity_watch_edit AFTER UPDATE ON watch WHEN OLD.status<>NEW.status OR OLD.favorite<>NEW.favorite BEGIN INSERT INTO user_activity(user_id,kind,target,summary,created_at) VALUES(NEW.user_id,'watch',NEW.video_id,'Set watch status to '||NEW.status||CASE WHEN NEW.favorite<>OLD.favorite THEN CASE WHEN NEW.favorite=1 THEN '; added to favorites' ELSE '; removed from favorites' END ELSE '' END,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER journey_activity_contact AFTER INSERT ON contact_messages  BEGIN INSERT INTO user_activity(user_id,kind,target,summary,created_at) VALUES(NEW.user_id,'contact',NEW.ticket_id,CASE WHEN NEW.moderator=1 THEN 'Replied to a contact request as moderator' ELSE 'Sent a contact message' END,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER journey_activity_preferences AFTER INSERT ON preferences  BEGIN INSERT INTO user_activity(user_id,kind,target,summary,created_at) VALUES(NEW.user_id,'preferences',NULL,'Saved display preferences',strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER journey_activity_preferences_edit AFTER UPDATE ON preferences WHEN OLD.settings<>NEW.settings BEGIN INSERT INTO user_activity(user_id,kind,target,summary,created_at) VALUES(NEW.user_id,'preferences',NULL,'Updated display preferences',strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER journey_activity_profile AFTER UPDATE OF name ON members WHEN OLD.name<>NEW.name BEGIN INSERT INTO user_activity(user_id,kind,summary,created_at) VALUES(NEW.id,'profile','Display name updated',strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
